  'cifra': { t: 'Cifra', d: 'Ciascuno dei simboli impiegati nella scrittura dei numeri. Nella notazione ordinaria le cifre sono dieci, da 0 a 9.', u: '0.3', s: 'hex', f: ['cifre'] },
  'riporto': { t: 'Riporto', d: 'Unità trasmessa alla posizione successiva quando una posizione ha esaurito le proprie cifre e ritorna a zero.', u: '0.3', s: 'pila', f: ['riporti'] },
  'posizione': { t: 'Posizione', d: 'Posto occupato da una cifra nella scrittura di un numero. Si numera da destra a partire da zero.', u: '0.3', s: 'puntatore', f: ['posizioni'] },
  'peso': { t: 'Peso', d: 'Valore che una posizione attribuisce alla cifra che la occupa. Nella notazione decimale i pesi sono 1, 10, 100 e così via.', u: '0.3', s: 'bilancio', f: ['pesi'] },
  'esperimento': { t: 'Esperimento', d: 'Simulazione posta al centro di ogni unità: una scena che mostra il funzionamento di un meccanismo del calcolatore, su dati modificabili.', u: '0.4', s: 'esperimento', f: ['esperimenti'] },
  'previsione': { t: 'Previsione', d: 'Risposta formulata prima dell’avvio di un esperimento, e confrontata al termine con l’esito.', u: '0.4', s: 'lente', f: ['previsioni'] },
