  'codice': { t: 'Codice (di un carattere)', d: 'Numero che corrisponde a un carattere secondo una tabella convenzionale. La lettera h ha codice 104.', u: '1.1.1', s: 'char', f: ['codici'] },
  'uscita standard': { t: 'Uscita standard (standard output)', d: 'Canale, già aperto all’avvio, al quale un programma trasmette il testo da scrivere.', u: '1.1.1', s: 'output' },
  'cella': { t: 'Cella', d: 'Elemento della memoria che conserva un dato. Le celle hanno tutte la stessa capacità e sono disposte in successione.', u: '1.1.2', s: 'memory', f: ['celle'] },
