  'linguaggio assembly': { t: 'Linguaggio assembly (assembly language)', d: 'Forma nella quale le istruzioni di uno specifico processore sono espresse con nomi leggibili, una per riga.', u: '1.1.3', s: 'tabella' },
  'codice macchina': { t: 'Codice macchina (machine code)', d: 'Istruzioni di un programma nella forma eseguita dal processore: una sequenza di numeri.', u: '1.1.3', s: 'cpu' },
  'file oggetto': { t: 'File oggetto (object file)', d: 'File prodotto dalla terza tappa della costruzione. Contiene il codice macchina del programma, con le chiamate alle funzioni di libreria ancora da collegare.', u: '1.1.3', s: 'file' },
  'linker': { t: 'Linker', d: 'Programma che riunisce il file oggetto e la libreria, collega ogni chiamata alla funzione corrispondente e produce il file eseguibile.', u: '1.1.3', s: 'bus' },
  'file eseguibile': { t: 'File eseguibile (executable file)', d: 'Ultimo file della catena di costruzione, il solo che il sistema operativo può caricare e avviare.', u: '1.1.3', s: 'riproduci' },
