  'tipo intero': { t: 'Tipo intero', d: 'Nel linguaggio C, dichiarazione che fissa per un numero intero la larghezza in bit e la lettura, con segno o senza segno.', u: '1.4.3', s: 'tabella', f: ['tipi interi'] },
  'estensione del segno': { t: 'Estensione del segno (sign extension)', d: 'Allargamento di un intero con segno ottenuto copiando il bit di segno in tutte le nuove posizioni, in modo che il valore resti invariato.', u: '1.4.3', s: 'segno' },
