  'ritardo di propagazione': { t: 'Ritardo di propagazione (propagation delay)', d: 'Tempo che l’uscita di una porta impiega per assestarsi dopo una variazione degli ingressi.', u: '1.5.4', s: 'clock' },
  'impulso transitorio': { t: 'Impulso transitorio', d: 'Valore errato e temporaneo sull’uscita di un circuito, dovuto a segnali che giungono con ritardi diversi.', u: '1.5.4', s: 'conflitto', f: ['impulsi transitori'] },
  'sommatore completo': { t: 'Sommatore completo (full adder)', d: 'Circuito di cinque porte che somma due bit e un riporto in arrivo, producendo il bit della somma e il riporto in uscita.', u: '1.5.5', s: 'alu', f: ['sommatori completi'] },
  'sommatore a propagazione di riporto': { t: 'Sommatore a propagazione di riporto (ripple-carry adder)', d: 'Serie di sommatori completi, uno per colonna, nella quale il riporto di ciascuno entra nel successivo.', u: '1.5.5', s: 'alu' },
  'bit di stato': { t: 'Bit di stato', d: 'Bit che registra una condizione a due valori, vero o falso. Più bit di stato sono raccolti nel medesimo byte.', u: '1.5.6', s: 'flag' },
  'operatore logico': { t: 'Operatore logico', d: 'Operatore del C che considera ogni operando come vero o falso e restituisce 0 oppure 1. Sono &&, || e !.', u: '1.5.6', s: 'conflitto', f: ['operatori logici'] },
  'cortocircuito': { t: 'Cortocircuito', d: 'Comportamento di && e ||, che omettono il calcolo del secondo operando quando il primo è sufficiente a determinare il risultato.', u: '1.5.6', s: 'scudo' },

  // Capitolo 1.6
